E["50:99165c28"] = "Колесо миші над карткою теж гортає сторінки."
E["50:9c7ac42b"] = "Нехай гравці знаходять вас на getmastercraft.com - безкоштовно."
E["50:dc9e7b19"] = "Mastercraft готовий. Три речі для початку:"
E["50:e9e531cc"] = "Їх зараз немає в Мережі Mastercraft."
E["50:f01a1ec8"] = "Щоб навчатися далі, просто поговоріть зі своїм майстром ще раз."
E["50:fac6bfaf"] = "Шляхи: Майстер-сокирник і Майстер-молотар закриваються назавжди."
E["51:1111349f"] = "Найкращий вихід і єдине джерело Магічних Кристалів."
E["51:1511e7d7"] = "Дізнайтеся, що розчаклувати або виставити на аукціон."
E["51:19510e71"] = "Забагато прохань одразу - спробуйте за кілька хвилин."
E["51:27ddcdc3"] = "Станьте в зоні з водою, щоб побачити, що там клює."
E["51:2c275292"] = "Натисніть, щоб обрати мову тексту Mastercraft."
E["51:652844ae"] = "Клік: що на них одягнено, їхні сумки, банк і пошта"
E["51:660a52c7"] = "Виготовляється, купується або особлива здобич - метал і камінь"
E["51:a2c8217e"] = "Запитано 1 майстра - він отримає вікно, щоб написати вам."
E["51:be430db5"] = "Жодна виплавка тут не дає очок вміння - підвищуйте вміння видобутком."
E["51:ce05e48b"] = "Можна вивчити зараз: вивчається при вашому найкращому умінні чи нижчому."
E["51:d2fec567"] = "Призначте клавішу: Прив'язки клавіш > Аддони > Mastercraft."
E["51:ddd50872"] = "-  |cffffb833не в гільдії, лише ваші персонажі|r"
E["51:fe02befc"] = "У вас 3 запити чекають - спершу дочекайтеся відповіді."
E["52:0177e265"] = "У бою: ваша клавіша риболовлі спрацює після бою."
E["52:10d0be27"] = "Відкрийте банк цього персонажа один раз, щоб побачити, що в ньому."
E["52:11e40698"] = "Заробляється доставкою заповнених ящиків із припасами."
E["52:1e864e8a"] = "Увійдіть один раз кожним персонажем, і він з'явиться тут"
E["52:260b2df5"] = "Відкрийте поштову скриньку цим персонажем один раз, щоб побачити її."
E["52:287ec9ee"] = "Зараз немає лотів - це остання побачена ціна."
E["52:32ad404b"] = "Ви запитували щойно - спробуйте знову за кілька хвилин."
E["52:46a0203d"] = "Відтоді шляху назад немає: Зброяр вам недоступний."
E["52:6a5f6464"] = "Підписавши обіцянку, ви назавжди втрачаєте доступ до: Інженерія гномів."
E["52:6f461882"] = "Натисніть «Закинути». Клацніть правою по поплавку, коли він сплескує."
E["52:a1ff0166"] = "Ціни ще немає - відкрийте аукціон, щоб її знайти."
E["52:aaf9487a"] = "На вас уже найкраще спорядження для риболовлі з ваших сумок."
E["52:b0d8342c"] = "Ваші улюблені майстри показано в картці «Обране»."
E["52:c0187dd4"] = "Спершу відкрийте вікно професії, потім натисніть «Створити»."
E["52:e56cce60"] = "Шляхи: Майстер-мечник і Майстер-молотар закриваються назавжди."
E["53:2a7e2888"] = "Клацніть для стрілки - найближчий з вашої фракції"
E["53:2e1799a4"] = "Гіпогрифи, ведмеді, мавпи й вовки по всьому Фераласу."
